INSERT INTO clinlims.observation_history_type (id, type_name, description, lastupdated)
SELECT nextval('clinlims.observation_history_type_seq'), 'TbTestRequest', 'TB_TEST_REQUEST', now()
WHERE NOT EXISTS (SELECT 1 FROM clinlims.observation_history_type WHERE type_name = 'TbTestRequest');
